-- IPA FY2022 exemption exam 2023-01-22: reviewed adaptations and exact repeats.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2022-20230122-q01','exam-fe','基数変換','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問1・改編】16進小数 0.248 を10進数の分数で表すとどれか。','[{"id":"a","text":"31/32"},{"id":"b","text":"31/125"},{"id":"c","text":"31/512"},{"id":"d","text":"73/512"}]','"d"','2/16＋4/256＋8/4096＝584/4096＝73/512。 中文：按16进制小数的各位权计算：2/16＋4/256＋8/4096＝73/512。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q05','exam-fe','奇数パリティ','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問5・改編】8ビットのデータ d0〜d7 に奇数パリティビット p を付ける。⊕を排他的論理和とすると、常に成り立つ式はどれか。','[{"id":"a","text":"p＝0"},{"id":"b","text":"d0⊕…⊕d7＝p"},{"id":"c","text":"d0⊕…⊕d7⊕p＝0"},{"id":"d","text":"d0⊕…⊕d7⊕p＝1"}]','"d"','奇数パリティではデータとパリティを合わせた1の個数が奇数なので、全ビットのXORは1となる。 中文：奇校验要求数据位和校验位中1的总数为奇数，因此所有位的异或结果为1。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q06','exam-fe','逆ポーランド記法','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問6・改編】式 ((A＋B)×(C＋D))÷(A−D) を逆ポーランド記法で表したものはどれか。','[{"id":"a","text":"AB＋CD＋×AD−÷"},{"id":"b","text":"AB＋CD＋AD−×÷"},{"id":"c","text":"ABCD＋＋×AD−÷"},{"id":"d","text":"ABCD＋＋÷AD−×"}]','"a"','各演算子をその2個の被演算子の後に置く。分子はAB＋CD＋×、分母はAD−で、最後に÷を置く。 中文：后缀表达式将运算符置于操作数之后；先写分子、分母，最后写除号。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q07','exam-fe','二分木の表現','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問7・改編】二分木を(左部分木,節番号,右部分木)で表し、空の部分木をxとする。根3の左の子2は左の子1のみ、右の子5は左に4・右に6を持つ。正しい表現はどれか。葉は番号だけで表してよい。','[{"id":"a","text":"((1,2),3,(4,5,6))"},{"id":"b","text":"((1,2,3),x,(4,5,6))"},{"id":"c","text":"((1,2,x),3,(4,5,6))"},{"id":"d","text":"((1,2,x),3,(6,5,4))"}]','"c"','節2には左の葉1と空の右部分木があり、節5には左4・右6がある。 中文：节点2的左子节点为1、右子树为空；节点5的左、右子节点分别为4和6。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q08','exam-fe','再帰と二項係数','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問8・改編】f(n,0)＝f(n,n)＝1、0＜k＜nでは f(n,k)＝f(n−1,k−1)＋f(n−1,k) とする。f(4,2) はどれか。','[{"id":"a","text":"3"},{"id":"b","text":"4"},{"id":"c","text":"5"},{"id":"d","text":"6"}]','"d"','f(4,2)＝f(3,1)＋f(3,2)＝3＋3＝6。二項係数4C2に相当する。 中文：由递推式得到 f(4,2)＝f(3,1)＋f(3,2)＝3＋3＝6。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q09','exam-fe','ブロック探索','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問9・改編】昇順のn個のデータをm個ずつに分け、まず各ブロックの末尾を線形探索し、該当ブロック内を線形探索する。データは必ず存在し各位置の確率は同じ、nはmの倍数、mは十分大きい。平均比較回数の近似式はどれか。','[{"id":"a","text":"m＋n/m"},{"id":"b","text":"m/2＋n/(2m)"},{"id":"c","text":"n/m"},{"id":"d","text":"n/(2m)"}]','"b"','ブロック数はn/mなので末尾の比較は平均約n/(2m)回、ブロック内は平均約m/2回。定数項を省く。 中文：先检查的块数平均约为 n/(2m)，块内查找平均约为 m/2，两者相加。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q11','exam-fe','アドレス指定','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問11・改編】命令のアドレス部が20で、主記憶のアドレス20には25が格納されている。次にアドレス25を参照してデータを得る方式はどれか。','[{"id":"a","text":"間接アドレス指定"},{"id":"b","text":"指標アドレス指定"},{"id":"c","text":"相対アドレス指定"},{"id":"d","text":"直接アドレス指定"}]','"a"','命令中のアドレスが実データではなく、そのアドレスを格納した場所を指すので間接指定である。 中文：指令中的地址先指向存放有效地址的位置，再通过该有效地址取得数据，属于间接寻址。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q12','exam-fe','パイプライン制御','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問12・改編】プロセッサのパイプライン制御を説明したものはどれか。','[{"id":"a","text":"コンパイラが命令ごとに使う演算器をあらかじめ割り振る"},{"id":"b","text":"実行段階で演算器を動的に割り当て複数命令を同時に実行する"},{"id":"c","text":"命令処理を複数の段階に分け、複数命令の異なる段階を重ねて実行する"},{"id":"d","text":"命令をマイクロ命令の組合せとして実行する"}]','"c"','フェッチ・解読・実行などを段階に分け、別々の命令を異なる段階で並行処理する。 中文：将取指、译码、执行等分成阶段，使不同指令的不同阶段重叠执行，提高吞吐量。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q13','exam-fe','投機実行','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問13・改編】CPUの投機実行の説明として適切なものはどれか。','[{"id":"a","text":"依存しない命令を出現順に関係なく実行する"},{"id":"b","text":"空き時間を利用して複数スレッドを実行する"},{"id":"c","text":"複数のCPUコアで複数スレッドを同時に動かす"},{"id":"d","text":"分岐先が確定する前に予測した先の命令の実行を始める"}]','"d"','分岐を予測して先行実行し、予測が外れた結果は破棄する。 中文：推测执行根据分支预测提前执行指令；预测错误时需丢弃错误路径的结果。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q14','exam-fe','磁気ディスクのアクセス時間','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問14・改編】磁気ディスクは6000回転/分、平均位置決め時間20ms、1トラック20kバイト。4kバイトを1ブロック転送する平均アクセス時間は何msか。制御のオーバーヘッドは無視する。','[{"id":"a","text":"20"},{"id":"b","text":"22"},{"id":"c","text":"27"},{"id":"d","text":"32"}]','"c"','1回転10ms、平均回転待ちは5ms。転送は1トラックの1/5なので2ms。20＋5＋2＝27ms。 中文：每圈10毫秒，平均旋转等待5毫秒；传输占一圈的1/5，即2毫秒，总计27毫秒。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q15','exam-fe','ライブマイグレーション','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問15・改編】仮想サーバのライブマイグレーションの説明はどれか。','[{"id":"a","text":"仮想サーバ上のOSやソフトウェアを停止せず、別の物理サーバへ移す"},{"id":"b","text":"利用頻度に応じデータを適切なストレージへ配置する"},{"id":"c","text":"共有データベースの内容を利用者ごとに分離する"},{"id":"d","text":"需要に応じて資源を動的に割り当て回収する"}]','"a"','ライブマイグレーションは稼働中の仮想マシンを別の物理ホストへ移動する技術である。 中文：实时迁移将运行中的虚拟机迁往另一台物理主机，尽量不中断业务。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q18','exam-fe','メモリの断片化','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問18・改編】OSが記憶領域の割当てと解放を繰り返し、小さな未使用領域が多数できる現象はどれか。','[{"id":"a","text":"コンパクション"},{"id":"b","text":"スワッピング"},{"id":"c","text":"フラグメンテーション"},{"id":"d","text":"ページング"}]','"c"','連続した空き領域が細切れになる現象をフラグメンテーションという。コンパクションは空き領域をまとめる操作。 中文：频繁分配和释放使空闲区域碎片化；压缩整理则是将这些空间合并的操作。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q19','exam-fe','ページ置換','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問19・改編】実記憶のページ枠は3個で最初は空。参照順が1,3,2,1,4,5,2,3,4,5のとき、初回の空き枠への読込みを除いたページ置換回数はどれか。左をFIFO、右をLRUとする。','[{"id":"a","text":"FIFO 3回、LRU 2回"},{"id":"b","text":"FIFO 3回、LRU 6回"},{"id":"c","text":"FIFO 4回、LRU 3回"},{"id":"d","text":"FIFO 5回、LRU 4回"}]','"b"','3枠を満たした後を追跡すると、FIFOは4・5・3の読込み時に置換し3回、LRUは4以降の未保持参照で6回。 中文：初次填满3个页框后逐次模拟：FIFO置换3次，LRU置换6次；首次装入空页框不计作置换。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q24','exam-fe','CG用語','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問24・改編】CGに関する説明として適切なものはどれか。','[{"id":"a","text":"アンチエイリアシングは標本化不足による現象そのもの"},{"id":"b","text":"クリッピングは曲面を陰影で表す処理"},{"id":"c","text":"レンダリングは表示領域外だけを切り取る処理"},{"id":"d","text":"ワイヤフレームは3次元形状を線で表す表現"}]','"d"','ワイヤフレームは形状の辺などを線で表す。クリッピングは表示領域に合わせた切取りである。 中文：线框模型用线条表示三维物体的边；裁剪是按显示区域截取图形。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q25','exam-fe','参照整合性','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問25・改編】建物表、部屋表、資産表があり、部屋は建物を、資産は部屋を参照する。新しい建物・部屋・資産を登録するとき、参照先の行を先に作る順序はどれか。','[{"id":"a","text":"資産→建物→部屋"},{"id":"b","text":"建物→部屋→資産"},{"id":"c","text":"部屋→資産→建物"},{"id":"d","text":"部屋→建物→資産"}]','"b"','外部キーの参照先を先に登録するため、建物、部屋、資産の順に作成する。 中文：遵守外键参照约束，应先创建被引用的建筑，再创建房间，最后登记资产。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q26','exam-fe','JDBC','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問26・改編】Javaアプリケーションからデータベースに接続するための標準APIはどれか。','[{"id":"a","text":"HTML"},{"id":"b","text":"Java VM"},{"id":"c","text":"JDBC"},{"id":"d","text":"SQL"}]','"c"','JDBCはJavaからデータベースへの接続やSQL実行を扱うAPIである。SQLは問い合わせ言語。 中文：JDBC是Java访问数据库的标准API；SQL是查询和操作数据库的语言。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q29','exam-fe','共有ロックと排他ロック','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問29・改編】同じデータに対し先行トランザクションと後続トランザクションがロックを取得する。共有と排他の組合せで同時に実行できるものはどれか。','[{"id":"a","text":"共有・共有、共有・排他、排他・共有"},{"id":"b","text":"共有・共有、排他・共有"},{"id":"c","text":"共有・共有、共有・排他"},{"id":"d","text":"共有・共有だけ"}]','"d"','共有ロック同士は両立する。いずれかが排他ロックであれば、他方は解除を待つ。 中文：同一数据上的共享锁可以共存；只要一方是排他锁，另一方就不能同时持有锁。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q31','exam-fe','ルータ','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問31・改編】ルータに関する適切な説明はどれか。','[{"id":"a","text":"MACアドレス表でフレームの転送ポートを選択する"},{"id":"b","text":"データリンク層でネットワークを接続する"},{"id":"c","text":"トランスポート層からアプリケーション層までのプロトコルを変換する"},{"id":"d","text":"異なるネットワークを接続し、IPアドレスに基づき転送経路を決定する"}]','"d"','ルータはネットワーク層で宛先IPアドレスと経路情報を使いパケットを転送する。 中文：路由器在网络层根据目标IP地址和路由表决定数据包的转发路径。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q32','exam-fe','DNS','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問32・改編】TCP/IPネットワークでホスト名をIPアドレスに変換する機能はどれか。','[{"id":"a","text":"ARP"},{"id":"b","text":"DHCP"},{"id":"c","text":"DNS"},{"id":"d","text":"SNMP"}]','"c"','DNSはドメイン名・ホスト名からIPアドレスを得る名前解決を提供する。 中文：DNS负责域名或主机名的解析；ARP、DHCP和SNMP分别承担其他网络功能。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q33','exam-fe','ホスト部のビット演算','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問33・改編】IPv4アドレスをa、サブネットマスクをmとする。~をビット反転、&をビットごとのAND、|をORとすると、ホスト部だけを取り出す式はどれか。','[{"id":"a","text":"~a & m"},{"id":"b","text":"~a | m"},{"id":"c","text":"a & ~m"},{"id":"d","text":"a | ~m"}]','"c"','マスクを反転するとホスト部が1になる。それとIPアドレスのANDを取ればホスト部だけ残る。 中文：将子网掩码按位取反后，主机位为1；再与IP地址按位与即可提取主机部分。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q36','exam-fe','オープンリダイレクト','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問36・改編】オープンリダイレクトを悪用した攻撃はどれか。','[{"id":"a","text":"HTMLメールに最初から偽サイトのリンクを記載する"},{"id":"b","text":"正規サイトのリダイレクト機能を悪用し、攻撃者指定の偽サイトへ誘導する"},{"id":"c","text":"DNS応答を大量送信しサーバの資源を枯渇させる"},{"id":"d","text":"公開プロキシを悪用して迷惑メールを送る"}]','"b"','遷移先の検証が不十分な正規サイトの転送機能を利用し、偽サイトへ誘導する。 中文：攻击者利用正规网站未充分验证跳转目标的功能，把用户转到伪造网站。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q37','exam-fe','EDoS','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問37・改編】従量課金のクラウドに対するEDoS攻撃の説明はどれか。','[{"id":"a","text":"金融機関のクラウドに侵入しカード情報を盗む"},{"id":"b","text":"課金機能に侵入して支払いを回避する"},{"id":"c","text":"大量の資源を消費させ、利用者に経済的損失を与える"},{"id":"d","text":"クラウド資源でパスワードを解析する"}]','"c"','EDoSは大量要求などで従量課金の資源消費を増大させ、費用負担を狙う。 中文：经济型拒绝服务攻击通过大量消耗云资源，使受害者产生高额费用。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q41','exam-fe','耐タンパ性','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問41・改編】IoTデバイスの耐タンパ性を高める実装とその効果として適切なものはどれか。','[{"id":"a","text":"軽量暗号で通信中の漏えいを防ぐ"},{"id":"b","text":"GPSで紛失した機器の位置を探す"},{"id":"c","text":"筐体が開けられたことを光センサで検知し、内部の秘密情報を消去する"},{"id":"d","text":"メモリカードを予備機に移して復旧する"}]','"c"','耐タンパ性は物理的な改ざんや内部情報の不正取得への抵抗性。開封検知と秘密消去がその例。 中文：防篡改能力旨在抵抗物理拆解和秘密信息窃取；检测开壳并删除密钥是典型措施。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q42','exam-fe','SIEM','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問42・改編】SIEMの機能はどれか。','[{"id":"a","text":"隔離環境でファイルを実行して挙動を監視する"},{"id":"b","text":"複数機器から収集したログを統合分析し、管理者の調査・対応を支援する"},{"id":"c","text":"ネットワーク機器の設定を集中的に変更する"},{"id":"d","text":"通信先アプリを識別してパケット通信を制御する"}]','"b"','SIEMは各種ログやイベントを相関分析し、単一ログでは見えにくい異常の検出を支援する。 中文：SIEM汇总并关联分析多个设备的日志和事件，帮助发现异常并支持响应。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q44','exam-fe','クロスサイトスクリプティング','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問44・改編】クロスサイトスクリプティング対策として適切なものはどれか。','[{"id":"a","text":"WebサーバでSNMPエージェントを稼働する"},{"id":"b","text":"OSにパッチを適用するだけ"},{"id":"c","text":"入力された文字が出力先でHTMLタグとして解釈されないよう処理する"},{"id":"d","text":"大きすぎる入力データだけを禁止する"}]','"c"','出力する場所に応じて適切にエスケープし、入力を実行可能なHTMLやスクリプトとして解釈させない。 中文：根据输出上下文正确转义用户输入，避免其被浏览器当作HTML或脚本执行。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q45','exam-fe','ソフトウェアの使用性','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問45・改編】ソフトウェアの使用性を高める取組はどれか。','[{"id":"a","text":"オンラインヘルプを充実し操作方法を理解しやすくする"},{"id":"b","text":"外部連携できる他システムを増やす"},{"id":"c","text":"利用できる業務機能の範囲を拡大する"},{"id":"d","text":"データの複製を分散して故障時の損失を減らす"}]','"a"','使用性は利用者にとっての理解しやすさや操作しやすさに関係する。 中文：可用性中的易用性关注用户是否容易理解和操作；完善帮助文档有助于提升易用性。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q47','exam-fe','バグ埋込み法','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問47・改編】テストで計48個のバグを発見した。この中に意図的に埋め込んだ22個のうち16個が含まれる。埋込みバグと元からのバグの発見割合が等しいとすると、埋込み分も含め残るバグは推定何個か。','[{"id":"a","text":"6"},{"id":"b","text":"10"},{"id":"c","text":"18"},{"id":"d","text":"22"}]','"c"','元の発見数は48−16＝32個。総数は32×22/16＝44個なので元の残り12個、未発見の埋込み6個を合わせ18個。 中文：已发现原有缺陷32个，按相同发现率估计原有缺陷共44个，还剩12个；加上6个人工缺陷，合计18个。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q49','exam-fe','回帰テスト','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問49・改編】回帰テストの説明として適切なものはどれか。','[{"id":"a","text":"新規モジュールのみの誤りを検出するテスト"},{"id":"b","text":"修正によって既存機能に想定外の影響がないか確認するテスト"},{"id":"c","text":"単体モジュールへのホワイトボックステストに限定されるテスト"},{"id":"d","text":"毎回テストケースとデータを全て作り直すテスト"}]','"b"','修正後に既存の機能を再検証し、変更に伴う退行を検出する。 中文：回归测试在修改后重新验证已有功能，发现变更引入的意外问题。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q50','exam-fe','リバースエンジニアリング','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問50・改編】保守に用いるリバースエンジニアリングの具体例はどれか。','[{"id":"a","text":"ソースプログラムを解析して仕様書を作る"},{"id":"b","text":"ソースを探索して修正箇所と影響範囲を調べる"},{"id":"c","text":"ソースを構造化プログラムに変換する"},{"id":"d","text":"ソースを読みやすい表現に書き換える"}]','"a"','既存の実装から仕様や設計など上位の情報を復元するのがリバースエンジニアリングである。 中文：逆向工程通过分析现有实现，恢复其规格、设计或结构等信息。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q52','exam-fe','ファンクションポイント法','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問52・改編】開発規模の見積りに使うファンクションポイント法の説明はどれか。','[{"id":"a","text":"既知の規模から工数と工期だけを算出する"},{"id":"b","text":"類似システムの実績と経験で規模を見積もる"},{"id":"c","text":"入出力やファイルなどの機能を数え複雑さを調整して規模を見積もる"},{"id":"d","text":"作業を単位項目に分け基準作業量を積算する"}]','"c"','外部入力・出力・照会やファイルなど、利用者から見た機能を基に規模を測定する。 中文：功能点法按用户可见的输入、输出、查询和文件等功能及其复杂度估算软件规模。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q53','exam-fe','保守性の指標','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問53・改編】ソフトウェアの保守性を定量評価する指標として適切なものはどれか。','[{"id":"a","text":"成果物中の誤り件数÷成果物量"},{"id":"b","text":"修正時間の合計÷修正件数"},{"id":"c","text":"変更が必要な行数÷移植する行数"},{"id":"d","text":"利用者の改良要求件数÷出荷後の月数"}]','"b"','1件当たりの平均修正時間は修正のしやすさを測る保守性の指標になる。 中文：每次修改的平均耗时可以反映维护和修复的难易程度。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q54','exam-fe','コミュニケーション経路','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問54・改編】10人のチームに2人を追加し、全員が他の全員と1対1で1回ずつ打合せを行う。追加前と比べ打合せは何回増えるか。','[{"id":"a","text":"12"},{"id":"b","text":"21"},{"id":"c","text":"22"},{"id":"d","text":"42"}]','"b"','12人の組合せは12×11/2＝66、10人では10×9/2＝45。差は21回。 中文：12人的两两组合为66对，10人为45对，因此增加21次。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q64','exam-fe','要件定義の合意形成','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問64・改編】社内業務システムの要件定義で、合意形成の対象に含めるべき関係者はどれか。','[{"id":"a","text":"開発要員を派遣する派遣元の責任者"},{"id":"b","text":"システムの運用・保守を担当する社内部門の責任者"},{"id":"c","text":"RFPを送付した全ベンダの責任者"},{"id":"d","text":"進捗管理ツールの提供元の責任者"}]','"b"','運用・保守部門は稼働後の要件や制約に関わるため、合意形成に参加する。 中文：负责后续运行和维护的部门直接受需求及约束影响，应参与需求共识。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q67','exam-fe','フォロワ戦略','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問67・改編】企業の競争戦略におけるフォロワ戦略はどれか。','[{"id":"a","text":"多方面で差別化し上位企業のシェアを奪う"},{"id":"b","text":"大手が参入しない専門市場に資源を集中する"},{"id":"c","text":"先行企業の戦略を観察し迅速に模倣して開発・広告費を抑える"},{"id":"d","text":"全顧客を対象に全方位で市場をカバーする"}]','"c"','フォロワは先行企業の成功事例を参考にし、模倣などで開発や市場開拓のコストを抑える。 中文：追随者观察并借鉴先行企业的策略，以降低研发和市场开拓成本。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q68','exam-fe','CRMの目的','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問68・改編】CRM（顧客関係管理）の目的はどれか。','[{"id":"a","text":"顧客ロイヤルティを高め顧客生涯価値を最大化する"},{"id":"b","text":"在庫不足による販売機会損失を削減する"},{"id":"c","text":"生産資材の発注量と時期を決める"},{"id":"d","text":"販売時点の各商品の販売情報を把握する"}]','"a"','CRMは顧客との関係を継続的に管理し、満足度や生涯価値の向上を目指す。 中文：客户关系管理通过维护长期客户关系，提高忠诚度和客户终身价值。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q72','exam-fe','コンカレントエンジニアリング','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問72・改編】製品開発を速めるため、社内資源を用いる組織的な取組に当たるものはどれか。','[{"id":"a","text":"既存のCAD・CAM・CAEツールを積極活用する"},{"id":"b","text":"社外の市場調査会社を活用する"},{"id":"c","text":"設計部門と生産部門の作業を並行して進める"},{"id":"d","text":"大学と共同研究し他社技術を導入する"}]','"c"','コンカレントエンジニアリングは部門間の作業を並行させる社内の組織的アプローチ。 中文：并行工程让设计和生产等部门同时协作，属于利用内部资源的组织方法。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q75','exam-fe','PDPC','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問75・改編】PDPCの説明として適切なものはどれか。','[{"id":"a","text":"意味の近い言語データをまとめて要約する"},{"id":"b","text":"各作業を時系列に並べ最短日程を算出する"},{"id":"c","text":"想定される不測の事態を考え、計画から結果までの過程と対応策を展開する"},{"id":"d","text":"目的と手段を階層的に展開し実施項目を決める"}]','"c"','PDPCは進行中に起こり得る事態と対応を展開し、目的に至る対策を検討する。 中文：过程决策计划图事先考虑执行中可能发生的情况及应对路径。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q77','exam-fe','ROI','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問77・改編】ROIの説明として適切なものはどれか。','[{"id":"a","text":"各期間のキャッシュフローを現在価値に換算した合計"},{"id":"b","text":"キャッシュフローの現在価値の合計を0にする割引率"},{"id":"c","text":"利益額を投資額で割り、投資に対する収益を評価する指標"},{"id":"d","text":"投資額の回収に要する期間"}]','"c"','ROIは投資に対する利益の割合。現在価値の合計はNPV、回収にかかる期間は回収期間。 中文：投资回报率通常以利润除以投资额衡量；净现值与回收期是其他评价方法。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20230122-q80','exam-fe','電子署名法','standard','single_choice','【IPA 2022年度 修了認定試験 2023-01-22 問80・改編】日本の電子署名法に関する説明として適切なものはどれか。','[{"id":"a","text":"コンピュータで処理できない記録にも電子署名が成立する"},{"id":"b","text":"一定の要件を満たす電子署名には、本人による成立を推定する効力が認められる"},{"id":"c","text":"認証業務は政府の認証局だけが行える"},{"id":"d","text":"電子署名は共通鍵暗号技術に限られる"}]','"b"','法の要件を満たす電子署名がされた電磁的記録には、本人による真正な成立の推定が認められる。 中文：符合法律条件的电子签名可使相关电子记录被推定为由本人真实成立。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20230122_FE.pdf','ja','A','explicit','standard','fe_exemption');
